import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import { loginDiscordBot, getDiscordClient, getGuildId } from './utils/discord';
import { logger } from './utils/logger';
import { authMiddleware } from './middleware/auth';
import { errorHandler, notFoundHandler } from './middleware/errorHandler';
import { startKeepAlive } from './utils/keepalive';

// APIエンドポイント
import { syncRoles } from './api/rolesSync';
import { syncAllRoles } from './api/rolesSyncAll';
import { getNickname, updateNickname } from './api/nickname';
import { createGeneration } from './api/generation';
import { getMemberStatus } from './api/memberStatus';
import { getAllMembers } from './api/members';
import { assignRole, removeRole, listDiscordRoles } from './api/roles';

const app = express();
const PORT = process.env.PORT || 3000;

// CORS設定
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',')
    : '*', // 本番環境では具体的なオリジンを指定することを推奨
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // プリフライトリクエストのキャッシュ時間（24時間）
};

// ミドルウェア
app.use(cors(corsOptions));
app.use(express.json());

// ヘルスチェック（認証不要）
app.get('/health', async (req, res) => {
  try {
    const client = getDiscordClient();
    const wsStatus = client.ws.status;
    const guildId = getGuildId();
    let guildOk = false;
    let guildError = '';
    try {
      const guild = await client.guilds.fetch(guildId);
      guildOk = !!guild;
    } catch (e: any) {
      guildError = e.message || 'Unknown error';
    }
    res.json({
      status: guildOk ? 'ok' : 'degraded',
      timestamp: new Date().toISOString(),
      discord: {
        ws_status: wsStatus,
        bot_user: client.user?.tag || null,
        guild_id: guildId,
        guild_accessible: guildOk,
        guild_error: guildError || undefined,
      },
    });
  } catch (e) {
    res.json({ status: 'ok', timestamp: new Date().toISOString(), discord: { error: 'Client not initialized' } });
  }
});

// 認証が必要なエンドポイント
app.post('/api/roles/sync', authMiddleware, syncRoles);
app.post('/api/roles/sync-all', authMiddleware, syncAllRoles);
app.post('/api/roles/assign', authMiddleware, assignRole);
app.post('/api/roles/remove', authMiddleware, removeRole);
app.get('/api/roles/discord-list', authMiddleware, listDiscordRoles);
app.get('/api/nickname', authMiddleware, getNickname);
app.post('/api/nickname/update', authMiddleware, updateNickname);
app.post('/api/generation', authMiddleware, createGeneration);
app.get('/api/member/status', authMiddleware, getMemberStatus);
app.get('/api/members', authMiddleware, getAllMembers);

// 404ハンドラー
app.use(notFoundHandler);

// エラーハンドラー
app.use(errorHandler);

// サーバー起動
const startServer = async () => {
  try {
    // Discord Botをログイン
    const discordToken = process.env.DISCORD_TOKEN;
    if (!discordToken) {
      throw new Error('DISCORD_TOKEN is not set in environment variables');
    }

    logger.info('Logging in Discord Bot...');
    await loginDiscordBot(discordToken);

    // Supabaseキープアライブを開始
    startKeepAlive();

    // Expressサーバーを起動
    app.listen(PORT, () => {
      logger.info(`🚀 Server is running on port ${PORT}`);
      logger.info(`API endpoints are ready`);
    });
  } catch (error) {
    logger.error('Failed to start server', error);
    process.exit(1);
  }
};

startServer();
```

# Bearer Token Authentication Middleware

Here is the complete source code provided:

```typescript
import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';

// Bearer Token認証ミドルウェア
export const authMiddleware = (req: Request, res: Response, next: NextFunction): void => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ 
      success: false, 
      error: 'Unauthorized: Bearer token required' 
    });
    return;
  }

  const token = authHeader.substring(7); // "Bearer "を除去

  // 環境変数からAPIトークンを取得
  const validToken = process.env.API_AUTH_TOKEN;

  if (!validToken) {
    logger.error('API_AUTH_TOKEN is not set in environment variables');
    res.status(500).json({ 
      success: false, 
      error: 'Server configuration error' 
    });
    return;
  }

  if (token !== validToken) {
    logger.warn(`Invalid token attempt from ${req.ip}`);
    res.status(401).json({ 
      success: false, 
      error: 'Unauthorized: Invalid token' 
    });
    return;
  }

  next();
};
```

## Overview

This Express.js middleware validates incoming requests using Bearer token authentication. It extracts the token from the Authorization header, compares it against an environment variable, and either permits passage to the next handler or returns an appropriate HTTP error response.

# Express Error Handling Middleware

Here is the complete source code as-is:

```typescript
import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';

// エラーハンドリングミドルウェア
export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  logger.error('Unhandled error:', err);

  res.status(500).json({
    success: false,
    error: 'Internal server error',
    details: process.env.NODE_ENV !== 'production' ? err.message : undefined,
  });
};

// 404ハンドラー
export const notFoundHandler = (req: Request, res: Response): void => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
};
```

## Overview

This TypeScript module exports two Express middleware functions. The error handler logs exceptions and returns a 500 status with sanitized error details (only exposing stack information in non-production environments). The 404 handler responds with a 404 status when routes aren't matched.

